dict(id="wizard-cipher", name="WIZARD cipher (reverse alphabet with pair drop-out)", category="classical-cipher",
 summary="Penn's name for an Atbash-like reverse alphabet (A<->Z, B<->Y ...). A letter next to its own mirror letter (a 'WIZARD pair') cancels and drops out.",
 rules="Letter n <-> letter 27 - n. Pairs of mutually mirrored letters (W/D, I/R, Z/A, G/T, P/K, F/U, V/E) are superfluous material and 'drop out'. The name: WIZARD -> DRAZIW, made entirely of pairs, so 'the word itself vanishes as if by magic'. Almost always used with anagram. Penn notes Jeremiah's atbash 'Sheshach' for Babel as precedent. The FBI Lab in 1981 recognized it as a 'standard cryptographic technique'.",
 examples=[
  X("WIZARD", "DRAZIW (W/D, I/R, Z/A are all pairs)", "The word vanishes.", ('ev',"wiz('WIZARD')=='DRAZIW'",True)),
  X("FV (340 cipher, and Exorcist figures)", "UE", "Eugene's code, which cannot be written in binary because of its leading dit.", ('ev',"wiz('FV')=='UE'",True)),
  X("NY (two characters before 340 crossed circle #4)", "MB", "Berta's code in mirror order.", ('ev',"wiz('NY')=='MB'",True)),
  X("BEVY, GRIT", "YVEB, TIRG", "Penn's illustrations.", ('ev',"wiz('BEVY')=='YVEB' and wiz('GRIT')=='TIRG'",True)),
 ],
 claims="Penn claims the Zodiac uses this Kabbalistic canon to hide UE and MB.",
 first_seen="1981 (named in the FBI Lab report of 26 Jun 1981)",
 citations=["T17:14-15", "T17:60-61", "T17:69", "T17:75", "T17:94", "T17:320", "T17:351 Appx B", "T17:353 Appx B", "FBI Lab report 26 Jun 1981"],
 demo=D("wizard", "WIZARD", "DRAZIW"),
 related=["wizard-anagram","family-monogram-codes","anagram"]),

