 first_seen="2010 (Letter to Zam); expanded 2022",
 citations=["Letter to Zam 16 Aug 2010", "SP:4", "Penn 2022, 'The real puzzle'", "Penn 2022, 'The Zodiac literature: digital, multidimensional, nonverbal'"],
